theorem iterate_one : f^[1] = f  := by
  funext _ ↦ rfl

@to_additive
theorem iterate_add : ∀ m : ℕ, ∀ n : ℕ, f^[m + n] = f^[m] ∘ f^[n]  := by
  intro m n; induction n with _ ih; simp [Nat.add_succ, iterate_succ] at *; exact ih

@to_additive (attr := simp)
theorem mul_succ : n * succ m = n * m + n  := by
  rw [Nat.mul_succ]; rfl

