lemma lemma_2
    (f : ℕ+ → ℕ+)
    (hf : ∀ n, f^[f n] n * f (f n) = n ^ 2)
    (m : ℕ+)
    (hm1 : f^[2] m = f^[f m] m)
    (hm2 : f^[f m] m = m)
    (hm3 : Odd m.val) :
    f m = m   := by
  let k := f m;
  _ := by rw [hm1, hm2, k];
  suffices f^[m] k = k := by rw [this, Function.iterate_one, Function.iterate_add, Function.iterate_add]; rfl;
  obtain ⟨m', hm'⟩ := hm3;
  +rwa [Function.iterate_one, Function.iterate_add, Function.iterate_add, hm', mul_left_eq_self_mul m', mul_left_comm]

